    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-03", "descripcion": "Comprende los roles que asumen los personajes en las obras literarias y su relación con la temática y la época en las que estas se desarrollan."},
    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-04", "descripcion": "Reconoce en la lectura de los distintos géneros literarios diferentes posibilidades de recrear y ampliar su visión de mundo."},
    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-05", "descripcion": "Comprende el sentido global de los mensajes, a partir de la relación entre la información explícita e implícita."},
    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-06", "descripcion": "Identifica la intención comunicativa de los textos con los que interactúa a partir del análisis de su contenido y estructura."},
    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-07", "descripcion": "Construye textos orales atendiendo a los contextos de uso, a los posibles interlocutores y a las líneas temáticas pertinentes con el propósito comunicativo en el que se enmarca el discurso."},
    {"area": "Lenguaje", "grado": "5", "codigo": "DBA-LG-5-08", "descripcion": "Produce textos verbales y no verbales a partir de los planes textuales que elabora según la tipología a desarrollar."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-01", "descripcion": "Utiliza la información ofrecida por los medios de comunicación, teniendo en cuenta el mensaje, los interlocutores, la intencionalidad y el contexto de producción, para participar en los procesos comunicativos de su entorno."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-02", "descripcion": "Crea organizadores gráficos en los que integra signos verbales y no verbales para dar cuenta de sus conocimientos."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-03", "descripcion": "Reconoce las obras literarias como una posibilidad de circulación del conocimiento y de desarrollo de su imaginación."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-04", "descripcion": "Identifica algunas expresiones de diferentes regiones y contextos en las obras literarias."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-05", "descripcion": "Interpreta obras de la tradición popular propias de su entorno."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-06", "descripcion": "Comprende diversos tipos de texto, a partir del análisis de sus contenidos, características formales e intenciones comunicativas."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-07", "descripcion": "Produce discursos orales y los adecúa a las circunstancias del contexto: el público, la intención comunicativa y el tema a desarrollar."},
    {"area": "Lenguaje", "grado": "6", "codigo": "DBA-LG-6-08", "descripcion": "Produce diversos tipos de texto atendiendo a los destinatarios, al medio en que se escribirá y a los propósitos comunicativos."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-01", "descripcion": "Clasifica la información que circula en los medios de comunicación con los que interactúa y la retoma como referente para sus producciones discursivas."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-02", "descripcion": "Reconoce las diferencias y semejanzas entre sistemas verbales y no verbales para utilizarlos en contextos escolares y sociales."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-03", "descripcion": "Establece conexiones entre los elementos presentes en la literatura y los hechos históricos, culturales y sociales en los que se han producido."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-04", "descripcion": "Clasifica las producciones literarias a partir del análisis de su contenido y estructura en diferentes géneros literarios."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-05", "descripcion": "Comprende discursos orales producidos con un objetivo determinado en diversos contextos sociales y escolares."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-06", "descripcion": "Interpreta textos informativos, expositivos, narrativos, líricos, argumentativos y descriptivos, y da cuenta de sus características formales y no formales."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-07", "descripcion": "Construye narraciones orales, para lo cual retoma las características de los géneros que quiere relatar y los contextos de circulación de su discurso."},
    {"area": "Lenguaje", "grado": "7", "codigo": "DBA-LG-7-08", "descripcion": "Produce textos verbales y no verbales conforme a las características de una tipología seleccionada, a partir de un proceso de planificación textual."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-01", "descripcion": "Caracteriza los discursos presentes en los medios de comunicación y otras fuentes de información, atendiendo al contenido, la intención comunicativa del autor y al contexto en que se producen."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-02", "descripcion": "Relaciona las manifestaciones artísticas con las comunidades y culturas en las que se producen."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-03", "descripcion": "Reconoce en las producciones literarias como cuentos, relatos cortos, fábulas y novelas, aspectos referidos a la estructura formal del género y a la identidad cultural que recrea."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-04", "descripcion": "Comprende que el género lírico es una construcción mediada por la musicalidad, la rima y el uso de figuras retóricas, que permiten recrear una idea, un sentimiento o una situación."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-05", "descripcion": "Escucha con atención a sus compañeros en diálogos informales y predice los contenidos de la comunicación."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-06", "descripcion": "Infiere múltiples sentidos en los textos que lee y los relaciona con los conceptos macro del texto y con sus contextos de producción y circulación."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-07", "descripcion": "Reconstruye en sus intervenciones el sentido de los textos desde la relación existente entre la temática, los interlocutores y el contexto histórico-cultural."},
    {"area": "Lenguaje", "grado": "8", "codigo": "DBA-LG-8-08", "descripcion": "Compone diferentes tipos de texto atendiendo a las características de sus ámbitos de uso: privado/público o cotidiano/científico."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-01", "descripcion": "Confronta los discursos provenientes de los medios de comunicación con los que interactúa en el medio para afianzar su punto de vista particular."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-02", "descripcion": "Incorpora símbolos de orden deportivo, cívico, político, religioso, científico o publicitario en los discursos que produces, teniendo claro su uso dentro del contexto."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-03", "descripcion": "Analiza el lenguaje literario como una manifestación artística que permite crear ficciones y expresar pensamientos o emociones."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-04", "descripcion": "Compara los formatos de obras literarias y de producciones audiovisuales con el propósito de analizar elementos propios de la narración."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-05", "descripcion": "Comprende y respeta las opiniones en debates sobre temas de actualidad social."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-06", "descripcion": "Interpreta textos atendiendo al funcionamiento de la lengua en situaciones de comunicación, a partir del uso de estrategias de lectura."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-07", "descripcion": "Produce textos orales, a partir del empleo de diversas estrategias para exponer sus argumentos."},
    {"area": "Lenguaje", "grado": "9", "codigo": "DBA-LG-9-08", "descripcion": "Produce textos verbales y no verbales, a partir de los planes textuales que elabora, y siguiendo procedimientos sistemáticos de corrección lingüística."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-01", "descripcion": "Asume una posición crítica y propositiva frente a los medios de comunicación masiva para analizar su influencia en la sociedad actual."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-02", "descripcion": "Planifica la producción de textos audiovisuales en los que articula elementos verbales y no verbales de la comunicación para desarrollar un tema o una historia."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-03", "descripcion": "Caracteriza la literatura en un momento particular de la historia desde el acercamiento a sus principales exponentes, textos, temáticas y recursos estilísticos."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-04", "descripcion": "Formula puntos de encuentro entre la literatura y las artes plásticas y visuales."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-05", "descripcion": "Participa en discursos orales en los que evalúa aspectos relacionados con la progresión temática, manejo de la voz, tono, estilo y puntos de vista sobre temas sociales, culturales, políticos y científicos."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-06", "descripcion": "Comprende diversos tipos de texto, asumiendo una actitud crítica y argumentando sus puntos de vista frente a lo leído."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-07", "descripcion": "Produce textos orales como ponencias, comentarios, relatorías o entrevistas, atendiendo a la progresión temática, a los interlocutores, al propósito y a la situación comunicativa."},
    {"area": "Lenguaje", "grado": "10", "codigo": "DBA-LG-10-08", "descripcion": "Escribe textos que evidencian procedimientos sistemáticos de corrección lingüística y el uso de estrategias de producción textual."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-01", "descripcion": "Participa en escenarios académicos, políticos y culturales; asumiendo una posición crítica y propositiva frente a los discursos que le presentan los distintos medios de comunicación y otras fuentes de información."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-02", "descripcion": "Expresa, con sentido crítico, cómo se articulan los códigos verbales y no verbales en diversas manifestaciones humanas y da cuenta de sus implicaciones culturales, sociales e ideológicas."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-03", "descripcion": "Determina los textos que desea leer y la manera en que abordará su comprensión, con base en sus experiencias de formación e inclinaciones literarias."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-04", "descripcion": "Identifica, en las producciones literarias clásicas, diferentes temas que le permiten establecer comparaciones con las visiones de mundo de otras épocas."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-05", "descripcion": "Comprende que los argumentos de sus interlocutores involucran procesos de comprensión, crítica y proposición."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-06", "descripcion": "Compara diversos tipos de texto, con capacidad crítica y argumentativa para establecer relaciones entre temáticas, características y los múltiples contextos en los que fueron producidos."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-07", "descripcion": "Expresa por medio de producciones orales el dominio de un tema, un texto o la obra de un autor."},
    {"area": "Lenguaje", "grado": "11", "codigo": "DBA-LG-11-08", "descripcion": "Produce textos académicos a partir de procedimientos sistemáticos de corrección lingüística, atendiendo al tipo de texto y al contexto comunicativo."},
    {"area": "Ciencias Naturales", "grado": "1", "codigo": "DBA-CN-1-01", "descripcion": "Comprende que los sentidos le permiten percibir algunas características de los objetos que nos rodean (temperatura, sabor, sonidos, olor, color, texturas y formas)."},
    {"area": "Ciencias Naturales", "grado": "1", "codigo": "DBA-CN-1-02", "descripcion": "Comprende que existe una gran variedad de materiales y que éstos se utilizan para distintos fines, según sus características (longitud, dureza, flexibilidad, permeabilidad al agua, solubilidad, ductilidad, maleabilidad, color, sabor, textura)."},
    {"area": "Ciencias Naturales", "grado": "1", "codigo": "DBA-CN-1-03", "descripcion": "Comprende que los seres vivos (plantas y animales) tienen características comunes (se alimentan, respiran, tienen un ciclo de vida, responden al entorno) y los diferencia de los objetos inertes."},
    {"area": "Ciencias Naturales", "grado": "1", "codigo": "DBA-CN-1-04", "descripcion": "Comprende que su cuerpo experimenta constantes cambios a lo largo del tiempo y reconoce a partir de su comparación que tiene características similares y diferentes a las de sus padres y compañeros."},
    {"area": "Ciencias Naturales", "grado": "2", "codigo": "DBA-CN-2-01", "descripcion": "Comprende que una acción mecánica (fuerza) puede producir distintas deformaciones en un objeto, y que este resiste a las fuerzas de diferente modo, de acuerdo con el material del que está hecho."},
    {"area": "Ciencias Naturales", "grado": "2", "codigo": "DBA-CN-2-02", "descripcion": "Comprende que las sustancias pueden encontrarse en distintos estados (sólido, líquido y gaseoso)."},
    {"area": "Ciencias Naturales", "grado": "2", "codigo": "DBA-CN-2-03", "descripcion": "Comprende la relación entre las características físicas de plantas y animales con los ambientes en donde viven, teniendo en cuenta sus necesidades básicas (luz, agua, aire, suelo, nutrientes, desplazamiento y protección)."},
    {"area": "Ciencias Naturales", "grado": "2", "codigo": "DBA-CN-2-04", "descripcion": "Explica los procesos de cambios físicos que ocurren en el ciclo de vida de plantas y animales de su entorno, en un período de tiempo determinado."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-01", "descripcion": "Comprende la forma en que se propaga la luz a través de diferentes materiales opacos, transparentes como el aire, translúcidos como el papel y reflectivos como el espejo."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-02", "descripcion": "Comprende la forma en que se produce la sombra y la relación de su tamaño con las distancias entre la fuente de luz, el objeto interpuesto y el lugar donde se produce la sombra."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-03", "descripcion": "Comprende la naturaleza fenómeno de la vibración y las características del sonido altura, timbre, intensidad y que este se propaga en distintos medios sólidos, líquidos, gaseosos."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-04", "descripcion": "Comprende la influencia de la variación de la temperatura en los cambios de estado de la materia, considerando como ejemplo el caso del agua."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-05", "descripcion": "Explica la influencia de los factores abióticos (luz, temperatura, suelo y aire) en el desarrollo de los factores bióticos (fauna y flora) de un ecosistema."},
    {"area": "Ciencias Naturales", "grado": "3", "codigo": "DBA-CN-3-06", "descripcion": "Comprende las relaciones de los seres vivos con otros organismos de su entorno (intra e interespecíficas) y las explica como esenciales para su supervivencia en un ambiente determinado."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-01", "descripcion": "Comprende que la magnitud y la dirección en que se aplica una fuerza puede producir cambios en la forma como se mueve un objeto (dirección y rapidez)."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-02", "descripcion": "Comprende los efectos y las ventajas de utilizar máquinas simples en diferentes tareas que requieren la aplicación de una fuerza."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-03", "descripcion": "Comprende que el fenómeno del día y la noche se debe a que la Tierra rota sobre su eje y en consecuencia el sol sólo ilumina la mitad de su superficie."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-04", "descripcion": "Comprende que las fases de la Luna se deben a la posición relativa del Sol, la Luna y la Tierra a lo largo del mes."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-05", "descripcion": "Comprende que existen distintos tipos de mezclas (homogéneas y heterogéneas) que de acuerdo con los materiales que las componen pueden separarse mediante diferentes técnicas (filtración, tamizado, decantación, evaporación)."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-06", "descripcion": "Comprende que los organismos cumplen distintas funciones en cada uno de los niveles tróficos y que las relaciones entre ellos pueden representarse en cadenas y redes alimenticias."},
    {"area": "Ciencias Naturales", "grado": "4", "codigo": "DBA-CN-4-07", "descripcion": "Comprende que existen distintos tipos de ecosistemas (terrestres y acuáticos) y que sus características físicas (temperatura, humedad, tipos de suelo, altitud) permiten que habiten en ellos diferentes seres vivos."},
    {"area": "Ciencias Naturales", "grado": "5", "codigo": "DBA-CN-5-01", "descripcion": "Comprende que un circuito eléctrico básico está formado por un generador o fuente (pila), conductores (cables) y uno o más dispositivos (bombillos, motores, timbres), que deben estar conectados apropiadamente (por sus dos polos) para que funcionen y produzcan diferentes efectos."},
    {"area": "Ciencias Naturales", "grado": "5", "codigo": "DBA-CN-5-02", "descripcion": "Comprende que algunos materiales son buenos conductores de la corriente eléctrica y otros no (denominados aislantes) y que el paso de la corriente siempre genera calor."},
    {"area": "Ciencias Naturales", "grado": "5", "codigo": "DBA-CN-5-03", "descripcion": "Comprende que los sistemas del cuerpo humano están formados por órganos, tejidos y células y que la estructura de cada tipo de célula está relacionada con la función del tejido que forman."},
    {"area": "Ciencias Naturales", "grado": "5", "codigo": "DBA-CN-5-04", "descripcion": "Comprende que en los seres humanos (y en muchos otros animales) la nutrición involucra el funcionamiento integrado de un conjunto de sistemas de órganos: digestivo, respiratorio y circulatorio."},
    {"area": "Ciencias Naturales", "grado": "6", "codigo": "DBA-CN-6-01", "descripcion": "Comprende cómo los cuerpos pueden ser cargados eléctricamente asociando esta carga a efectos de atracción y repulsión."},
    {"area": "Ciencias Naturales", "grado": "6", "codigo": "DBA-CN-6-02", "descripcion": "Comprende que la temperatura (T) y la presión (P) influyen en algunas propiedades fisicoquímicas (solubilidad, viscosidad, densidad, puntos de ebullición y fusión) de las sustancias, y que estas pueden ser aprovechadas en las técnicas de separación de mezclas."},
    {"area": "Ciencias Naturales", "grado": "6", "codigo": "DBA-CN-6-03", "descripcion": "Comprende la clasificación de los materiales a partir de grupos de sustancias (elementos y compuestos) y mezclas (homogéneas y heterogéneas)."},
    {"area": "Ciencias Naturales", "grado": "6", "codigo": "DBA-CN-6-04", "descripcion": "Comprende algunas de las funciones básicas de la célula (transporte de membrana, obtención de energía y división celular) a partir del análisis de su estructura."},
    {"area": "Ciencias Naturales", "grado": "6", "codigo": "DBA-CN-6-05", "descripcion": "Comprende la clasificación de los organismos en grupos taxonómicos, de acuerdo con el tipo de células que poseen y reconoce la diversidad de especies que constituyen nuestro planeta y las relaciones de parentesco entre ellas."},
    {"area": "Ciencias Naturales", "grado": "7", "codigo": "DBA-CN-7-01", "descripcion": "Comprende las formas y las transformaciones de energía en un sistema mecánico y la manera como, en los casos reales, la energía se disipa en el medio (calor, sonido)."},
    {"area": "Ciencias Naturales", "grado": "7", "codigo": "DBA-CN-7-02", "descripcion": "Explica cómo las sustancias se forman a partir de la interacción de los elementos y que estos se encuentran agrupados en un sistema periódico."},
    {"area": "Ciencias Naturales", "grado": "7", "codigo": "DBA-CN-7-03", "descripcion": "Comprende que en las cadenas y redes tróficas existen flujos de materia y energía, y los relaciona con procesos de nutrición, fotosíntesis y respiración celular."},
    {"area": "Ciencias Naturales", "grado": "7", "codigo": "DBA-CN-7-04", "descripcion": "Comprende la relación entre los ciclos del carbono, el nitrógeno y del agua, explicando su importancia en el mantenimiento de los ecosistemas."},
    {"area": "Ciencias Naturales", "grado": "8", "codigo": "DBA-CN-8-01", "descripcion": "Comprende el funcionamiento de máquinas térmicas (motores de combustión, refrigeración) por medio de las leyes de la termodinámica (primera y segunda ley)."},
    {"area": "Ciencias Naturales", "grado": "8", "codigo": "DBA-CN-8-02", "descripcion": "Comprende que en una reacción química se recombina los átomos de las moléculas de los reactivos para generar productos nuevos, y que dichos productos se forman a partir de fuerzas intramoleculares (enlaces iónicos y covalentes)."},
    {"area": "Ciencias Naturales", "grado": "8", "codigo": "DBA-CN-8-03", "descripcion": "Comprende que el comportamiento de un gas ideal está determinado por las relaciones entre Temperatura (T), Presión (P), Volumen (V) y Cantidad de sustancia (n)."},
    {"area": "Ciencias Naturales", "grado": "8", "codigo": "DBA-CN-8-04", "descripcion": "Analiza relaciones entre sistemas de órganos (excretor, inmune, nervioso, endocrino, óseo y muscular) con los procesos de regulación de las funciones en los seres vivos."},
    {"area": "Ciencias Naturales", "grado": "8", "codigo": "DBA-CN-8-05", "descripcion": "Analiza la reproducción (asexual, sexual) de distintos grupos de seres vivos y su importancia para la preservación de la vida en el planeta."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-01", "descripcion": "Comprende que el movimiento de un cuerpo, en un marco de referencia inercial dado, se puede describir con gráficos y predecir por medio de expresiones matemáticas."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-02", "descripcion": "Comprende que la acidez y la basicidad son propiedades químicas de algunas sustancias y las relaciona con su importancia biológica y su uso cotidiano e industrial."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-03", "descripcion": "Analiza las relaciones cuantitativas entre solutos y solventes, así como los factores que afectan la formación de soluciones."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-04", "descripcion": "Comprende la forma en que los principios genéticos mendelianos y post-mendelianos explican la herencia y el mejoramiento de las especies existentes."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-05", "descripcion": "Explica la forma como se expresa la información genética contenida en el ADN, relacionando su expresión con los fenotipos de los organismos y reconoce su capacidad de modificación a lo largo del tiempo (por mutaciones y otros cambios), como un factor determinante en la generación de diversidad del planeta y en la evolución de las especies."},
    {"area": "Ciencias Naturales", "grado": "9", "codigo": "DBA-CN-9-06", "descripcion": "Analiza teorías científicas sobre el origen de las especies (selección natural y ancestro común) como modelos científicos que sustentan sus explicaciones desde diferentes evidencias y argumentaciones."},
    {"area": "Ciencias Naturales", "grado": "10", "codigo": "DBA-CN-10-01", "descripcion": "Comprende que el reposo o el movimiento rectilíneo uniforme, se presentan cuando las fuerzas aplicadas sobre el sistema se anulan entre ellas, y que en presencia de fuerzas resultantes no nulas se producen cambios de velocidad."},
    {"area": "Ciencias Naturales", "grado": "10", "codigo": "DBA-CN-10-02", "descripcion": "Comprende la conservación de la energía mecánica como un principio que permite cuantificar y explicar diferentes fenómenos mecánicos: choques entre cuerpos, movimiento pendular, caída libre, deformación de un sistema masa-resorte."},
    {"area": "Ciencias Naturales", "grado": "10", "codigo": "DBA-CN-10-03", "descripcion": "Comprende que los diferentes mecanismos de reacción química (oxido-reducción, descomposición, neutralización y precipitación) posibilitan la formación de compuestos inorgánicos."},
    {"area": "Ciencias Naturales", "grado": "10", "codigo": "DBA-CN-10-04", "descripcion": "Comprende que la biotecnología conlleva el uso y manipulación de la información genética a través de distintas técnicas (fertilización asistida, clonación reproductiva y terapéutica, modificación genética, terapias génicas), y que tiene implicaciones sociales, bioéticas y ambientales."},
    {"area": "Ciencias Naturales", "grado": "11", "codigo": "DBA-CN-11-01", "descripcion": "Comprende la naturaleza de la propagación del sonido y de la luz como fenómenos ondulatorios (ondas mecánicas y electromagnéticas, respectivamente)."},
    {"area": "Ciencias Naturales", "grado": "11", "codigo": "DBA-CN-11-02", "descripcion": "Comprende que la interacción de las cargas en reposo genera fuerzas eléctricas y que cuando las cargas están en movimiento genera fuerzas magnéticas."},
    {"area": "Ciencias Naturales", "grado": "11", "codigo": "DBA-CN-11-03", "descripcion": "Comprende las relaciones entre corriente y voltaje en circuitos resistivos sencillos en serie, en paralelo y mixtos."},
    {"area": "Ciencias Naturales", "grado": "11", "codigo": "DBA-CN-11-04", "descripcion": "Comprende que los diferentes mecanismos de reacción química (oxido-reducción, homólisis, heterólisis y pericíclicas) posibilitan la formación de distintos tipos de compuestos orgánicos."},
    {"area": "Ciencias Naturales", "grado": "11", "codigo": "DBA-CN-11-05", "descripcion": "Analiza cuestiones ambientales actuales, como el calentamiento global, contaminación, tala de bosques y minería, desde una visión sistémica (económico, social, ambiental y cultural)."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-01", "descripcion": "Toma decisiones frente a algunas situaciones cotidianas."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-02", "descripcion": "Se apropia de hábitos y prácticas para el cuidado personal y de su entorno."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-03", "descripcion": "Identifica y valora las características corporales y emocionales en sí mismo y en los demás."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-04", "descripcion": "Reconoce que es parte de una familia, de una comunidad y un territorio con costumbres, valores y tradiciones."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-05", "descripcion": "Participa en la construcción colectiva de acuerdos, objetivos y proyectos comunes."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-06", "descripcion": "Demuestra consideración y respeto al relacionarse con otros."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-07", "descripcion": "Expresa y representa lo que observa, siente, piensa e imagina, a través del juego, la música, el dibujo y la expresión corporal."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-08", "descripcion": "Identifica las relaciones sonoras en el lenguaje oral."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-09", "descripcion": "Establece relaciones e interpreta imágenes, letras, objetos, personajes que encuentra en distintos tipos de textos."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-10", "descripcion": "Expresa ideas, intereses y emociones a través de sus propias grafías y formas semejantes a las letras convencionales en formatos con diferentes intenciones comunicativas."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-11", "descripcion": "Crea situaciones y propone alternativas de solución a problemas cotidianos a partir de sus conocimientos e imaginación."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-12", "descripcion": "Establece relaciones entre las causas y consecuencias de los acontecimientos que le suceden a él o a su alrededor."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-13", "descripcion": "Usa diferentes herramientas y objetos con variadas posibilidades."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-14", "descripcion": "Construye nociones de espacio, tiempo y medida a través de experiencias cotidianas."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-15", "descripcion": "Compara, ordena, clasifica objetos e identifica patrones de acuerdo con diferentes criterios."},
    {"area": "Transición", "grado": "0", "codigo": "DBA-TR-0-16", "descripcion": "Determina la cantidad de objetos que conforman una colección, al establecer relaciones de correspondencia y acciones de juntar y separar."},
    {"area": "Matemáticas", "grado": "1", "codigo": "DBA-MA-1-06", "descripcion": "Describe y representa trayectorias y posiciones de objetos y personas para orientar a otros o a sí mismo en el espacio circundante."},
    {"area": "Matemáticas", "grado": "8", "codigo": "DBA-MA-8-05", "descripcion": "Encuentra el volumen de objetos regulares e irregulares en la solución de problemas."},
    {"area": "Matemáticas", "grado": "8", "codigo": "DBA-MA-8-06", "descripcion": "Interpreta y analiza las gráficas y propiedades de expresiones algebraicas y relaciona variación y covariación con comportamientos gráficos."},
    {"area": "Matemáticas", "grado": "8", "codigo": "DBA-MA-8-07", "descripcion": "Reconoce y determina la probabilidad de eventos compuestos usando propiedades básicas de la probabilidad."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-01", "descripcion": "Utiliza las propiedades de los números reales para justificar procedimientos y representaciones de subconjuntos."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-02", "descripcion": "Utiliza las propiedades de los números reales para analizar procesos infinitos y resolver problemas."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-03", "descripcion": "Encuentra relaciones entre el área y la capacidad de cuerpos redondos (cilindro, cono, esfera)."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-04", "descripcion": "Interpreta el espacio de manera analítica a partir de relaciones geométricas en trayectorias y desplazamientos de cuerpos."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-05", "descripcion": "Usa lenguaje aritmético, geométrico o algebraico para formular y resolver conjeturas en problemas cotidianos."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-06", "descripcion": "Compara distribuciones de datos usando diagramas de caja, medidas de tendencia central, variación y localización."},
    {"area": "Matemáticas", "grado": "9", "codigo": "DBA-MA-9-07", "descripcion": "Encuentra posibles resultados de experimentos aleatorios y probabilidad de eventos compuestos."},
    {"area": "Matemáticas", "grado": "10", "codigo": "DBA-MA-10-01", "descripcion": "Reconoce el significado de magnitudes relacionales (velocidad media, aceleración media) a partir de tablas, gráficas y expresiones algebraicas."},
    {"area": "Matemáticas", "grado": "10", "codigo": "DBA-MA-10-02", "descripcion": "Comprende y utiliza funciones para modelar fenómenos periódicos y justifica las soluciones."},
    {"area": "Matemáticas", "grado": "10", "codigo": "DBA-MA-10-03", "descripcion": "Usa el concepto de cambio para estudiar el cambio promedio y el cambio alrededor de un punto."},
    {"area": "Matemáticas", "grado": "10", "codigo": "DBA-MA-10-04", "descripcion": "Comprende y usa medidas de tendencia central y dispersión, y complementa una medida con otra para mejores lecturas de datos."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-01", "descripcion": "Utiliza las propiedades de los números naturales, enteros, racionales y reales para construir y comparar sistemas numéricos."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-02", "descripcion": "Aplica la noción de derivada como razón de cambio para resolver problemas, estimar cantidades y juzgar la pertinencia de soluciones."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-03", "descripcion": "Diseña técnicas para mediciones con niveles crecientes de precisión."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-04", "descripcion": "Comprende la derivada como pendiente de la tangente y desarrolla métodos para hallar derivadas de funciones básicas."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-05", "descripcion": "Usa modelos funcionales para analizar situaciones y estudiar la variación en contextos intraescolares y extraescolares."},
    {"area": "Matemáticas", "grado": "11", "codigo": "DBA-MA-11-06", "descripcion": "Resuelve problemas que implican exploración de asociaciones o correlaciones entre variables."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-01", "descripcion": "Identifica las características de los medios de comunicación masiva a los que tiene acceso."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-02", "descripcion": "Identifica la función que cumplen las señales y símbolos que aparecen en su entorno."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-03", "descripcion": "Reconoce elementos de textos literarios como personajes, espacios y acciones."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-04", "descripcion": "Comprende diversos textos literarios a partir de sus propias vivencias."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-05", "descripcion": "Expresa sus ideas atendiendo a las características del contexto comunicativo (interlocutores, temas, lugares)."},
    {"area": "Lenguaje", "grado": "2", "codigo": "DBA-LG-2-06", "descripcion": "Produce diferentes tipos de textos para atender a un propósito comunicativo particular."},
    {"area": "Lenguaje", "grado": "3", "codigo": "DBA-LG-3-01", "descripcion": "Comprende las funciones que cumplen los medios de comunicación propios de su contexto."},
    {"area": "Lenguaje", "grado": "3", "codigo": "DBA-LG-3-02", "descripcion": "Reconoce elementos de textos narrativos como narrador y estructura narrativa."},
    {"area": "Lenguaje", "grado": "3", "codigo": "DBA-LG-3-03", "descripcion": "Escribe textos literarios coherentes, atendiendo a las características textuales e integrando sus saberes e intereses."},
    {"area": "Lenguaje", "grado": "3", "codigo": "DBA-LG-3-04", "descripcion": "Produce textos orales breves ajustando el volumen, el tono de la voz, los movimientos corporales y los gestos."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-01", "descripcion": "Se ubica en el espacio que habita teniendo como referencia su propio cuerpo y los puntos cardinales."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-02", "descripcion": "Describe las características del paisaje geográfico del barrio, vereda o lugar donde vive, sus componentes y formas."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-03", "descripcion": "Describe el tiempo personal y se sitúa en secuencias de eventos propios y sociales."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-04", "descripcion": "Reconoce la noción de cambio a partir de las transformaciones que ha vivido en los últimos años a nivel personal, de su familia y del entorno barrial, veredal o del lugar donde vive."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-05", "descripcion": "Reconoce su individualidad y su pertenencia a los diferentes grupos sociales."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-06", "descripcion": "Comprende cambios en las formas de habitar de los grupos humanos, desde el reconocimiento de los tipos de vivienda que se encuentran en el contexto de su barrio, vereda o lugar donde vive."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-07", "descripcion": "Participa en la construcción de acuerdos básicos sobre normas para el logro de metas comunes en su contexto cercano (compañeros y familia) y se compromete con su cumplimiento."},
    {"area": "Ciencias Sociales", "grado": "1", "codigo": "DBA-CS-1-08", "descripcion": "Establece relaciones de convivencia desde el reconocimiento y el respeto de sí mismo y de los demás."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-01", "descripcion": "Comprende que el paisaje que vemos es resultado de las acciones humanas que se realizan en un espacio geográfico y que por esta razón, dicho paisaje cambia."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-02", "descripcion": "Reconoce los puntos cardinales y los usa para orientarse en el desplazamiento de un lugar a otro."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-03", "descripcion": "Comprende la importancia de las fuentes históricas para la construcción de la memoria individual, familiar y colectiva."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-04", "descripcion": "Explica cambios y continuidades en los medios empleados por las personas para transportarse en su municipio, vereda o lugar donde vive."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-05", "descripcion": "Analiza las actividades económicas de su entorno y el impacto de estas en la comunidad."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-06", "descripcion": "Compara las características de las viviendas de su municipio, vereda o lugar donde vive con las de otros lugares."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-07", "descripcion": "Reconoce la organización territorial en su municipio, desde: comunas, corregimientos, veredas, localidades y territorios indígenas."},
    {"area": "Ciencias Sociales", "grado": "2", "codigo": "DBA-CS-2-08", "descripcion": "Reconoce y rechaza situaciones de exclusión o discriminación en su familia, entre sus amigos y en los compañeros del salón de clase."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-01", "descripcion": "Comprende la importancia de los océanos y mares en la organización económica y social de los pueblos costeros en la actualidad."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-02", "descripcion": "Relaciona las características biogeográficas de su departamento, municipio, resguardo o lugar donde vive, con las actividades económicas que en ellos se realizan."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-03", "descripcion": "Explica las acciones humanas que han incidido en las transformaciones del territorio asociadas al número de habitantes e infraestructura, en su departamento, municipio, resguardo o lugar donde vive."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-04", "descripcion": "Comprende el legado de los grupos humanos en la gastronomía, la música y el paisaje de la región, municipio, resguardo o lugar donde vive."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-05", "descripcion": "Comprende la importancia del tiempo en la organización de las actividades sociales, económicas y culturales en su comunidad."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-06", "descripcion": "Analiza las contribuciones de los grupos humanos que habitan en su departamento, municipio o lugar donde vive, a partir de sus características culturales: lengua, organización social, tipo de vivienda, cosmovisión y uso del suelo."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-07", "descripcion": "Comprende la importancia de participar en las decisiones de su comunidad cercana (institución educativa) mediante la elección del gobierno escolar."},
    {"area": "Ciencias Sociales", "grado": "3", "codigo": "DBA-CS-3-08", "descripcion": "Comprende la estructura y el funcionamiento democrático a nivel del departamento como entidad política, administrativa y jurídica."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-01", "descripcion": "Comprende la importancia de los límites geográficos y el establecimiento de las fronteras en la organización de los territorios."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-02", "descripcion": "Diferencia las características geográficas del medio urbano y el medio rural, mediante el reconocimiento de la concentración de la población y el uso del suelo, que se da en ellos."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-03", "descripcion": "Comprende las razones de algunos cambios socioculturales en Colombia, motivados en los últimos años por el uso de la tecnología."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-04", "descripcion": "Analiza las características de las culturas ancestrales que a la llegada de los españoles, habitaban el territorio nacional."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-05", "descripcion": "Evalúa la diversidad étnica y cultural del pueblo colombiano desde el reconocimiento de los grupos humanos existentes en el país: afrodescendientes, raizales, mestizos, indígenas y blancos."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-06", "descripcion": "Comprende la importancia de la división de poderes en una democracia y la forma como funciona en Colombia."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-07", "descripcion": "Analiza los derechos que protegen la niñez y los deberes que deben cumplirse en una sociedad democrática para el desarrollo de una sana convivencia."},
    {"area": "Ciencias Sociales", "grado": "4", "codigo": "DBA-CS-4-08", "descripcion": "Evalúa la importancia de satisfacer las necesidades básicas para el bienestar individual, familiar y colectivo."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-01", "descripcion": "Comprende la organización territorial existente en Colombia y las particularidades geográficas de las regiones."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-02", "descripcion": "Comprende las ventajas que tiene para Colombia su posición geográfica y astronómica en relación con la economía nacional."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-03", "descripcion": "Comprende que los cambios en la comunicación originados por los avances tecnológicos han generado transformaciones en la forma como se relacionan las personas en la sociedad actual."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-04", "descripcion": "Analiza el periodo colonial en la Nueva Granada a partir de sus organizaciones políticas, económicas y sociales."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-05", "descripcion": "Analiza el origen y consolidación de Colombia como república y sus cambios políticos, económicos y sociales."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-06", "descripcion": "Analiza los cambios ocurridos en la sociedad colombiana en la primera mitad del siglo XX, asociados a la expansión de la industria y el establecimiento de nuevas redes de comunicación."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-07", "descripcion": "Comprende que en la sociedad colombiana existen derechos, deberes, principios y acciones para orientar y regular la convivencia de las personas."},
    {"area": "Ciencias Sociales", "grado": "5", "codigo": "DBA-CS-5-08", "descripcion": "Analiza el papel de las organizaciones sociales en la preservación y el reconocimiento de los Derechos Humanos."},
    {"area": "Ciencias Sociales", "grado": "6", "codigo": "DBA-CS-6-01", "descripcion": "Comprende que existen diversas explicaciones y teorías sobre el origen del universo en nuestra búsqueda por entender que hacemos parte de un mundo más amplio."},
