async def seed() -> tuple[int, int]:
    created = 0
    updated = 0
    async with AsyncSessionLocal() as db:
        for item in DBA_ITEMS:
            existing = await db.scalar(
                select(DBACatalog).where(DBACatalog.codigo == item["codigo"])
            )
            fuente = FUENTES.get(item["area"], "")
            if existing:
                existing.area = item["area"]
                existing.grado = item["grado"]
                existing.descripcion = item["descripcion"]
                existing.fuente = fuente
                existing.activo = True
                updated += 1
            else:
                db.add(DBACatalog(
                    area=item["area"], grado=item["grado"],
                    codigo=item["codigo"], descripcion=item["descripcion"],
                    fuente=fuente, activo=True,
                ))
                created += 1
        await db.commit()
    return created, updated

def main() -> None:
    created, updated = asyncio.run(seed())
    print(f"DBA completo: created={created} updated={updated} total={created + updated}")

if __name__ == "__main__":
    main()
